import csv, io
from datetime import date

text = 'name,age,price,joined\nAna,34,19.99,2026-01-05\nBo,9,5.50,2026-02-11\nCy,,N/A,not-a-date\n'
rows = list(csv.DictReader(io.StringIO(text)))

def convert(row):
    out, errors = {}, []
    for field, fn in [('age', int), ('price', float), ('joined', date.fromisoformat)]:
        try:
            out[field] = fn(row[field])
        except (ValueError, TypeError):
            errors.append((field, row[field]))
    out['name'] = row['name']
    return out, errors

for row in rows:
    out, errors = convert(row)
    print(out['name'], '->', {k: type(v).__name__ for k, v in out.items() if k != 'name'}, '| errors:', errors)

def guess(data):
    if data.startswith(b'\xef\xbb\xbf'):
        return 'utf-8-sig (BOM present)'
    if data.startswith(b'\xff\xfe') or data.startswith(b'\xfe\xff'):
        return 'utf-16 (BOM present)'
    try:
        data.decode('utf-8')
        return 'valid utf-8 (ascii is a subset - cannot distinguish)'
    except UnicodeDecodeError:
        return 'not utf-8 - a single-byte encoding, exact one unknowable'

samples = {
    'utf-8 with BOM': b'\xef\xbb\xbfhello',
    'utf-16 with BOM': 'hello'.encode('utf-16'),
    'plain ascii': b'hello',
    'utf-8 accented': 'café'.encode('utf-8'),
    'cp1252 bytes': b'\x93quoted\x94 \x80',
}
for name, data in samples.items():
    print(f'{name:16} -> {guess(data)}')

