SIGNATURES = [
    (b'\x89PNG\r\n\x1a\n', 'PNG image'),
    (b'\xff\xd8\xff', 'JPEG image'),
    (b'PK\x03\x04', 'ZIP archive'),
    (b'\x1f\x8b', 'gzip stream'),
    (b'%PDF', 'PDF document'),
]

def identify(data):
    for magic, label in SIGNATURES:
        if data.startswith(magic):
            return label
    return 'unknown'

