    'notes.txt': b'just some plain text',
}
for name in sorted(files):
    print(f'{name:12} extension suggests one thing, bytes say: {identify(files[name])}')

from html.parser import HTMLParser

PAGE = '''<html><head><title>My Page</title><script>var x = "not content";</script></head>
<body><h1>Welcome</h1><p>First paragraph.</p><p>Second <b>paragraph</b>.</p></body></html>'''

class TextGrabber(HTMLParser):
    def __init__(self):
        super().__init__()
        self.skip = 0
        self.chunks = []
    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style'):
            self.skip += 1
    def handle_endtag(self, tag):
        if tag in ('script', 'style') and self.skip:
            self.skip -= 1
    def handle_data(self, data):
        if not self.skip and data.strip():
            self.chunks.append(data.strip())

g = TextGrabber()
g.feed(PAGE)
print(g.chunks)

import re
from html.parser import HTMLParser

html = '<div class="item"><div class="item">inner</div> outer</div>'
m = re.search(r'<div class="item">(.*?)</div>', html)
print('regex captured:', repr(m.group(1)))

class DivText(HTMLParser):
    def __init__(self):
        super().__init__()
        self.depth = 0
        self.text = []
    def handle_starttag(self, tag, attrs):
        if tag == 'div':
            self.depth += 1
    def handle_endtag(self, tag):
        if tag == 'div':
            self.depth -= 1
    def handle_data(self, data):
        if self.depth >= 1:
            self.text.append(data.strip())

p = DivText()
p.feed(html)
print('parser collected:', [t for t in p.text if t])

import csv, io
from datetime import datetime

text = ('name,when,amount\n'
        ' Ana ,2026-01-05,"$1,200.50"\n'
        'Bo,01/05/2026, 75 \n'
        'Cy,5 Jan 2026,"$2,000"\n'
        'Di,2026-13-40,$10\n'
        'Ed,2026-02-01,abc\n')
FORMATS = ['%Y-%m-%d', '%m/%d/%Y', '%d %b %Y']

def parse_date(s):
    for fmt in FORMATS:
        try:
            return datetime.strptime(s, fmt).date().isoformat()
        except ValueError:
            continue
    return None

kept, rejects = [], []
for lineno, row in enumerate(csv.DictReader(io.StringIO(text)), start=2):
    name = row['name'].strip()
    when = parse_date(row['when'].strip())
    try:
        amount = float(row['amount'].strip().replace('$', '').replace(',', ''))
    except ValueError:
        amount = None
    if when is None:
        rejects.append((lineno, name, 'unparseable date'))
    elif amount is None:
        rejects.append((lineno, name, 'unparseable amount'))
    else:
        kept.append((name, when, amount))
print('kept:', kept)
print('rejects:', rejects)

