import csv, io

text = ('id,email\n'
        '1,ana@example.com\n'
        '2, BO@example.com \n'
        '3,junk\n'
        '4,cy@example.com\n'
        '5,\n'
        '6,di@example.com\n')
counts = {'read': 0, 'cleaned': 0, 'kept': 0}

def read_stage(text):
    for row in csv.DictReader(io.StringIO(text)):
        counts['read'] += 1
        yield row

def clean_stage(rows):
    for row in rows:
        row['email'] = row['email'].strip().lower()
        counts['cleaned'] += 1
        yield row

def filter_stage(rows):
    for row in rows:
        if '@' in row['email']:
            counts['kept'] += 1
            yield row

kept = list(filter_stage(clean_stage(read_stage(text))))
print('kept ids:', [r['id'] for r in kept])
print('stage counts:', counts)

