import csv, io, json

text = 'id,code,price\n1,007,1.50\n2,042,2.00\n3,123,9.99\n'
source = list(csv.DictReader(io.StringIO(text)))
CONVERTERS = {'id': int, 'price': float}
converted = [{k: CONVERTERS[k](v) if k in CONVERTERS else v for k, v in row.items()}
             for row in source]
cells_changed = 0
for s_row, c_row in zip(source, converted):
    for key in s_row:
        if str(c_row[key]) != s_row[key]:
            cells_changed += 1
print('rows in:', len(source), '| rows out:', len(converted))
print('cells whose text representation changed:', cells_changed)
print('example: code stayed text:', converted[0]['code'], '| price became:', converted[0]['price'])

